/* ================= v5.2: career-level interviews and small talk =================
   role: intern | grad | eng | senior | lawyer | exec ; partner lines may hold variants separated by "||" (one is picked per attempt) */
SCENES.push(
/* ---------- INTERVIEWS (professional) ---------- */
{id:"iv_intern", ctx:"pro", role:"intern", kind:"iv", title:{en:"Interview: internship",de:"Vorstellungsgespräch: Praktikum",fr:"Entretien : stage"}, turns:{
 en:[
  ["Hello and welcome! Please tell us a little about yourself and your studies.||Nice to meet you. Could you start by introducing yourself and what you are studying?","Introduce yourself: name, subject, semester and one interest related to the job.","Hello, thank you for having me. My name is Sam Weber, I study mechanical engineering in my fifth semester. I am especially interested in product development, which is why I applied here.","my name|i am|i m; study|studying|student|degree|semester|university; interest|interested|passion|enjoy"],
  ["Why do you want to do your internship with us?||What attracted you to this internship?","Give two concrete reasons connected to the company.","First, your company develops electric drives, and that is exactly the field I want to work in later. Second, I would like to apply what I learned at university in a real project team.","first|one reason|because; second|also|and; company|products|team|project|field"],
  ["Tell us about a group project at university. What was your role?||Can you describe a team project you were part of and what you contributed?","Describe the project, your task and what you learned.","In a team of four we built a small solar-powered vehicle. I was responsible for the calculations and the schedule. I learned how important clear communication and fixed deadlines are.","team|group|project; responsible|my role|my task|i did|i was; learned|learnt|experience|result"],
  ["Do you have any questions for us?||Is there anything you would like to know about the internship?","Ask a good question about tasks or mentoring and thank them.","Yes, thank you. Will I have a mentor during the internship, and which project could I work on? Thank you very much for the interview.","will|could|which|what|how|would; thank"]],
 de:[
  ["Hallo und herzlich willkommen! Erzählen Sie uns bitte etwas über sich und Ihr Studium.||Schön, Sie kennenzulernen. Stellen Sie sich doch bitte kurz vor – was studieren Sie?","Stell dich vor: Name, Studienfach, Semester und ein Interesse, das zur Stelle passt.","Hallo, vielen Dank für die Einladung. Mein Name ist Sam Weber, ich studiere Maschinenbau im fünften Semester. Besonders interessiert mich die Produktentwicklung, deshalb habe ich mich hier beworben.","mein name|ich bin|ich heiße; studiere|studium|semester|hochschule|universität; interess|begeister|spaß"],
  ["Warum möchten Sie Ihr Praktikum bei uns machen?||Was hat Sie an diesem Praktikum angesprochen?","Nenne zwei konkrete Gründe mit Bezug zum Unternehmen.","Erstens entwickelt Ihr Unternehmen elektrische Antriebe, und genau in diesem Bereich möchte ich später arbeiten. Zweitens möchte ich das Gelernte aus dem Studium in einem echten Projektteam anwenden.","erstens|ein grund|weil; zweitens|außerdem|auch; unternehmen|firma|produkt|team|projekt|bereich"],
  ["Erzählen Sie von einem Gruppenprojekt im Studium. Welche Rolle hatten Sie?||Beschreiben Sie bitte ein Teamprojekt und was Sie dazu beigetragen haben.","Beschreibe das Projekt, deine Aufgabe und was du gelernt hast.","In einem Team zu viert haben wir ein kleines solarbetriebenes Fahrzeug gebaut. Ich war für die Berechnungen und den Zeitplan verantwortlich. Dabei habe ich gelernt, wie wichtig klare Kommunikation und feste Termine sind.","team|gruppe|projekt; verantwortlich|meine aufgabe|meine rolle|ich habe|ich war; gelernt|erfahrung|ergebnis"],
  ["Haben Sie noch Fragen an uns?||Gibt es etwas, das Sie über das Praktikum wissen möchten?","Stell eine gute Frage zu Aufgaben oder Betreuung und bedanke dich.","Ja, danke. Habe ich während des Praktikums eine feste Ansprechperson, und an welchem Projekt könnte ich mitarbeiten? Vielen Dank für das Gespräch.","habe ich|gibt es|welche|welchem|wie|könnte|wer; dank"]],
 fr:[
  ["Bonjour et bienvenue ! Parlez-nous un peu de vous et de vos études.||Enchanté. Pouvez-vous commencer par vous présenter et nous dire ce que vous étudiez ?","Présentez-vous : nom, matière, semestre et un intérêt lié au poste.","Bonjour, merci de me recevoir. Je m'appelle Sam Weber, je suis en cinquième semestre de génie mécanique. Je m'intéresse surtout au développement de produits, c'est pourquoi j'ai postulé ici.","je m'appelle|je suis|mon nom; étudi|études|semestre|université|école; intéress|passion|aime"],
  ["Pourquoi voulez-vous faire votre stage chez nous ?||Qu'est-ce qui vous a attiré dans ce stage ?","Donnez deux raisons concrètes liées à l'entreprise.","D'abord, votre entreprise développe des moteurs électriques, et c'est exactement le domaine dans lequel je veux travailler plus tard. Ensuite, j'aimerais appliquer ce que j'ai appris à l'université dans une vraie équipe de projet.","d'abord|premièrement|parce que; ensuite|deuxièmement|aussi; entreprise|produit|équipe|projet|domaine"],
  ["Parlez-nous d'un projet de groupe à l'université. Quel était votre rôle ?||Pouvez-vous décrire un projet d'équipe et votre contribution ?","Décrivez le projet, votre tâche et ce que vous avez appris.","En équipe de quatre, nous avons construit un petit véhicule solaire. J'étais responsable des calculs et du planning. J'ai appris à quel point une communication claire et des délais fixes sont importants.","équipe|groupe|projet; responsable|mon rôle|ma tâche|j'étais|j'ai; appris|expérience|résultat"],
  ["Avez-vous des questions pour nous ?||Y a-t-il quelque chose que vous aimeriez savoir sur le stage ?","Posez une bonne question sur les missions ou l'encadrement et remerciez.","Oui, merci. Aurai-je un tuteur pendant le stage, et sur quel projet pourrais-je travailler ? Merci beaucoup pour cet entretien.","aurai|y a-t-il|quel|quelle|comment|pourrais|est-ce; merci"]]}},
{id:"iv_grad", ctx:"pro", role:"grad", kind:"iv", title:{en:"Interview: graduate / entry level",de:"Vorstellungsgespräch: Berufseinstieg",fr:"Entretien : jeune diplômé"}, turns:{
 en:[
  ["Congratulations on your degree. What was your thesis about?||Tell me about your final thesis – what did you work on?","Explain your thesis topic simply and name one result.","Thank you. My thesis was about reducing energy use in office buildings. I simulated different control strategies, and the best one saved about fifteen percent of heating energy.","thesis|dissertation|topic|about; simulat|analy|developed|tested|studied|research; result|saved|showed|found|percent"],
  ["Why did you choose our graduate programme?||What makes our trainee programme the right next step for you?","Connect the programme to your goals.","Your programme rotates through three departments, so I can learn the business from different sides. That fits my goal of becoming a project manager in a few years.","programme|program|rotation|department|training; goal|want|aim|plan|future; learn|grow|develop"],
  ["What would you say is one of your weaknesses?||Which skill do you still want to improve?","Name a real weakness and what you do about it.","Sometimes I spend too much time perfecting details. I have learned to set priorities and agree on deadlines early, so I can focus on what matters most for the result.","sometimes|weakness|improve|tend to; learned|learnt|working on|now i|so i; priorit|deadline|focus|plan"],
  ["Where do you see yourself in five years?||How would you like your career to develop over the next years?","Describe a realistic goal and how you will get there.","In five years I would like to lead my own projects and take responsibility for a small team. To get there, I want to gain experience in different projects and keep learning.","five years|future|years; lead|responsib|manage|team|projects; experience|learn|develop|grow"]],
 de:[
  ["Herzlichen Glückwunsch zum Abschluss. Worum ging es in Ihrer Abschlussarbeit?||Erzählen Sie mir von Ihrer Abschlussarbeit – woran haben Sie gearbeitet?","Erkläre das Thema deiner Abschlussarbeit einfach und nenne ein Ergebnis.","Vielen Dank. In meiner Masterarbeit ging es darum, den Energieverbrauch in Bürogebäuden zu senken. Ich habe verschiedene Regelstrategien simuliert, und die beste hat etwa fünfzehn Prozent Heizenergie eingespart.","arbeit|thema|ging es; simuliert|untersucht|entwickelt|getestet|analys; ergebnis|eingespart|gezeigt|prozent"],
  ["Warum haben Sie sich für unser Traineeprogramm entschieden?||Was macht unser Traineeprogramm zum richtigen nächsten Schritt für Sie?","Verbinde das Programm mit deinen Zielen.","Ihr Programm führt durch drei Abteilungen, so lerne ich das Unternehmen von verschiedenen Seiten kennen. Das passt zu meinem Ziel, in einigen Jahren Projektleiter zu werden.","programm|abteilung|trainee|rotation; ziel|möchte|will|plane|zukunft; lerne|kennen|entwickeln"],
  ["Was würden Sie als eine Ihrer Schwächen bezeichnen?||Welche Fähigkeit möchten Sie noch verbessern?","Nenne eine echte Schwäche und was du dagegen tust.","Manchmal verbringe ich zu viel Zeit damit, Details zu perfektionieren. Ich habe gelernt, Prioritäten zu setzen und früh Termine abzustimmen, damit ich mich auf das Wichtigste konzentriere.","manchmal|schwäche|verbessern|neige; gelernt|arbeite daran|inzwischen|deshalb; priorit|termin|konzentrier|plan"],
  ["Wo sehen Sie sich in fünf Jahren?||Wie soll sich Ihre Laufbahn in den nächsten Jahren entwickeln?","Beschreibe ein realistisches Ziel und den Weg dorthin.","In fünf Jahren möchte ich eigene Projekte leiten und Verantwortung für ein kleines Team übernehmen. Dafür will ich Erfahrung in verschiedenen Projekten sammeln und weiter lernen.","fünf jahren|zukunft|jahren; leiten|verantwortung|team|projekt; erfahrung|lernen|entwickeln"]],
 fr:[
  ["Félicitations pour votre diplôme. Sur quoi portait votre mémoire ?||Parlez-moi de votre travail de fin d'études – sur quoi avez-vous travaillé ?","Expliquez simplement le sujet de votre mémoire et donnez un résultat.","Merci. Mon mémoire portait sur la réduction de la consommation d'énergie dans les bureaux. J'ai simulé plusieurs stratégies de régulation, et la meilleure a économisé environ quinze pour cent d'énergie de chauffage.","mémoire|sujet|portait|thèse; simulé|analysé|développé|testé|étudié; résultat|économisé|montré|pour cent"],
  ["Pourquoi avez-vous choisi notre programme jeunes diplômés ?||Qu'est-ce qui fait de notre programme la bonne étape pour vous ?","Reliez le programme à vos objectifs.","Votre programme passe par trois services, je peux donc découvrir l'entreprise sous différents angles. Cela correspond à mon objectif de devenir chef de projet dans quelques années.","programme|service|département|formation; objectif|veux|souhaite|avenir; découvrir|apprendre|évoluer"],
  ["Quel serait l'un de vos points faibles ?||Quelle compétence souhaitez-vous encore améliorer ?","Citez un vrai point faible et ce que vous faites pour l'améliorer.","Parfois, je passe trop de temps à perfectionner les détails. J'ai appris à fixer des priorités et à convenir tôt des délais, pour me concentrer sur l'essentiel.","parfois|point faible|améliorer|j'ai tendance; appris|travaille|maintenant|donc; priorit|délai|concentr|plan"],
  ["Où vous voyez-vous dans cinq ans ?||Comment souhaitez-vous que votre carrière évolue dans les prochaines années ?","Décrivez un objectif réaliste et comment l'atteindre.","Dans cinq ans, j'aimerais diriger mes propres projets et être responsable d'une petite équipe. Pour cela, je veux acquérir de l'expérience sur différents projets et continuer à apprendre.","cinq ans|avenir|années; diriger|responsab|équipe|projet; expérience|apprendre|évoluer"]]}},
{id:"iv_eng", ctx:"pro", role:"eng", kind:"iv", title:{en:"Interview: engineer",de:"Vorstellungsgespräch: Ingenieur/in",fr:"Entretien : ingénieur(e)"}, turns:{
 en:[
  ["Describe a technical problem you solved recently.||Walk me through a difficult technical issue you fixed.","Use situation – analysis – solution – result.","A pump kept failing after a few weeks. I analysed the operating data and found that it ran far outside its design point. We changed the control settings, and since then it has run without failure for over a year.","problem|issue|failure|failing|fault; analys|measured|found|root cause|investigat; changed|solution|fixed|replaced|redesign; result|since|now|reduced"],
  ["How do you make sure your designs are safe and meet the requirements?||What do you do to ensure quality in your engineering work?","Name concrete methods (requirements, reviews, tests).","I start from clear, testable requirements. Then I use design reviews with colleagues, risk analyses like an FMEA, and I verify every requirement with a test or calculation before release.","requirement|specification|standard; review|check|fmea|risk|analysis; test|verif|validat|calculation"],
  ["Tell me about a disagreement with a colleague. How did you handle it?||Have you ever had a conflict in a project team? What happened?","Show that you listen, use facts and find a solution.","A colleague wanted a cheaper material that I thought was too weak. I listened to his arguments, we ran a quick calculation together and chose a middle solution that met both cost and strength targets.","colleague|disagree|conflict|different opinion; listened|talked|discussed|understood; data|calculation|facts|test; solution|agreed|compromise|together"],
  ["Which tools and software do you use in your daily work?||What is your technical toolbox?","Name tools and say what you use them for.","I mainly use CAD for design, a simulation tool for strength calculations and Python for data analysis. For project tracking we work with a ticket system.","cad|software|tool|simulation|python|matlab|excel; design|calculation|analysis|model; use|work with"]],
 de:[
  ["Beschreiben Sie ein technisches Problem, das Sie vor Kurzem gelöst haben.||Erzählen Sie mir Schritt für Schritt von einem schwierigen technischen Problem, das Sie behoben haben.","Nutze Situation – Analyse – Lösung – Ergebnis.","Eine Pumpe ist immer wieder nach wenigen Wochen ausgefallen. Ich habe die Betriebsdaten ausgewertet und festgestellt, dass sie weit außerhalb ihres Auslegungspunkts lief. Wir haben die Regelung angepasst, und seitdem läuft sie über ein Jahr ohne Ausfall.","problem|ausgefallen|ausfall|fehler|defekt; ausgewertet|analys|gemessen|festgestellt|ursache; angepasst|lösung|behoben|geändert|ersetzt; seitdem|ergebnis|jetzt|weniger"],
  ["Wie stellen Sie sicher, dass Ihre Konstruktionen sicher sind und die Anforderungen erfüllen?||Was tun Sie, um die Qualität Ihrer Arbeit sicherzustellen?","Nenne konkrete Methoden (Anforderungen, Reviews, Tests).","Ich beginne mit klaren, prüfbaren Anforderungen. Dann nutze ich Design-Reviews mit Kollegen, Risikoanalysen wie eine FMEA und weise jede Anforderung vor der Freigabe mit einem Test oder einer Berechnung nach.","anforderung|lastenheft|norm|spezifikation; review|prüfung|fmea|risiko|analyse; test|nachweis|nachweise|verifi|validier|berechnung"],
  ["Erzählen Sie von einer Meinungsverschiedenheit mit einem Kollegen. Wie sind Sie damit umgegangen?||Hatten Sie schon einmal einen Konflikt im Projektteam? Was ist passiert?","Zeig, dass du zuhörst, mit Fakten arbeitest und eine Lösung findest.","Ein Kollege wollte ein günstigeres Material, das ich für zu schwach hielt. Ich habe mir seine Argumente angehört, wir haben gemeinsam schnell nachgerechnet und eine Zwischenlösung gewählt, die Kosten- und Festigkeitsziele erfüllt.","kollege|meinung|konflikt|uneinig; angehört|gesprochen|besprochen|verstanden; gerechnet|daten|fakten|test|berechnung; lösung|geeinigt|kompromiss|gemeinsam"],
  ["Mit welchen Werkzeugen und Programmen arbeiten Sie im Alltag?||Was gehört zu Ihrem technischen Werkzeugkasten?","Nenne Werkzeuge und wofür du sie nutzt.","Ich nutze vor allem CAD für die Konstruktion, ein Simulationsprogramm für Festigkeitsberechnungen und Python für die Datenauswertung. Für die Projektverfolgung arbeiten wir mit einem Ticketsystem.","cad|software|programm|werkzeug|simulation|python|matlab|excel; konstruktion|berechnung|auswertung|modell; nutze|arbeite|verwende"]],
 fr:[
  ["Décrivez un problème technique que vous avez résolu récemment.||Expliquez-moi pas à pas un problème technique difficile que vous avez réglé.","Utilisez situation – analyse – solution – résultat.","Une pompe tombait en panne après quelques semaines. J'ai analysé les données de fonctionnement et constaté qu'elle fonctionnait loin de son point nominal. Nous avons modifié la régulation, et depuis, elle fonctionne sans panne depuis plus d'un an.","problème|panne|défaut|défaillance; analysé|mesuré|constaté|cause; modifié|solution|réglé|remplacé|changé; depuis|résultat|maintenant|réduit"],
  ["Comment vous assurez-vous que vos conceptions sont sûres et conformes aux exigences ?||Que faites-vous pour garantir la qualité de votre travail ?","Citez des méthodes concrètes (exigences, revues, essais).","Je pars d'exigences claires et vérifiables. Ensuite, j'organise des revues de conception avec des collègues, des analyses de risques comme une AMDEC, et je vérifie chaque exigence par un essai ou un calcul avant la validation.","exigence|cahier des charges|norme|spécification; revue|contrôle|amdec|risque|analyse; essai|test|vérifi|valid|calcul"],
  ["Parlez-moi d'un désaccord avec un collègue. Comment l'avez-vous géré ?||Avez-vous déjà eu un conflit dans une équipe projet ? Que s'est-il passé ?","Montrez que vous écoutez, utilisez des faits et trouvez une solution.","Un collègue voulait un matériau moins cher que je trouvais trop faible. J'ai écouté ses arguments, nous avons fait un calcul rapide ensemble et choisi une solution intermédiaire qui respectait les objectifs de coût et de résistance.","collègue|désaccord|conflit|avis; écouté|discuté|parlé|compris; calcul|données|faits|essai; solution|accord|compromis|ensemble"],
  ["Quels outils et logiciels utilisez-vous au quotidien ?||Quelle est votre boîte à outils technique ?","Citez des outils et à quoi ils vous servent.","J'utilise surtout la CAO pour la conception, un outil de simulation pour les calculs de résistance et Python pour l'analyse de données. Pour le suivi de projet, nous travaillons avec un système de tickets.","cao|logiciel|outil|simulation|python|matlab|excel; conception|calcul|analyse|modèle; utilise|travaille"]]}},
{id:"iv_senior", ctx:"pro", role:"senior", kind:"iv", title:{en:"Interview: senior engineer",de:"Vorstellungsgespräch: Senior-Ingenieur/in",fr:"Entretien : ingénieur(e) senior"}, turns:{
 en:[
  ["Tell me about an important technical decision you made and the trade-offs involved.||Describe a design decision where you had to balance competing goals.","Name the options, your criteria and why you chose one.","We had to choose between developing a new controller and adapting an existing one. I compared cost, risk and time to market. We adapted the existing platform, which saved six months, and planned the new design for the next generation.","decision|decide|choose|chose|choice|option; cost|risk|time|criteria|trade; because|saved|result|therefore|so"],
  ["How do you support and develop junior engineers?||What is your approach to mentoring less experienced colleagues?","Give concrete examples of mentoring.","I give juniors real responsibility for a well-defined part of the project and meet them weekly. I review their work with questions instead of answers, so they learn to find solutions themselves.","junior|colleague|team|mentor; responsib|task|ownership|weekly|regular; review|feedback|questions|learn|coach"],
  ["The deadline cannot move, but the tests show a problem. What do you do?||Your project is behind schedule and a key test failed. How do you react?","Show priorities: safety, transparency, options.","First, I make sure the problem is understood and that safety is not affected. Then I inform the stakeholders immediately and present options, for example a reduced scope on time or the full scope two weeks later.","safety|risk|understand|analy; inform|stakeholder|transparent|communicat|manager|customer; option|scope|plan|alternative|later"],
  ["How do you explain complex technical topics to non-technical managers?||How do you communicate with decision makers outside engineering?","Explain your communication method.","I start with the decision they need to make and the impact on cost, time and risk. Then I use one simple picture or comparison and leave the technical details for the appendix.","decision|impact|business|cost|risk; simple|picture|example|comparison|story|clear; details|appendix|questions|short"]],
 de:[
  ["Erzählen Sie von einer wichtigen technischen Entscheidung und den Zielkonflikten dabei.||Beschreiben Sie eine Entwurfsentscheidung, bei der Sie gegensätzliche Ziele abwägen mussten.","Nenne die Optionen, deine Kriterien und warum du dich entschieden hast.","Wir mussten zwischen einer Neuentwicklung der Steuerung und der Anpassung einer bestehenden wählen. Ich habe Kosten, Risiko und Markteinführung verglichen. Wir haben die bestehende Plattform angepasst, sechs Monate gespart und die Neuentwicklung für die nächste Generation eingeplant.","entscheid|entschieden|wählen|gewählt|option|alternative; kosten|risiko|zeit|kriterien|abwäg; weil|gespart|ergebnis|deshalb|daher"],
  ["Wie unterstützen und fördern Sie Nachwuchsingenieure?||Wie gehen Sie beim Mentoring weniger erfahrener Kollegen vor?","Gib konkrete Beispiele für dein Mentoring.","Ich gebe Einsteigern echte Verantwortung für einen klar abgegrenzten Projektteil und treffe sie wöchentlich. Ihre Arbeit bespreche ich mit Fragen statt fertigen Antworten, damit sie lernen, selbst Lösungen zu finden.","junior|einsteiger|nachwuchs|kolleg|team|mentor; verantwortung|aufgabe|wöchentlich|regelmäßig; feedback|fragen|bespreche|lernen|coach"],
  ["Der Termin ist fix, aber die Tests zeigen ein Problem. Was tun Sie?||Ihr Projekt liegt hinter dem Plan und ein wichtiger Test ist gescheitert. Wie reagieren Sie?","Zeig Prioritäten: Sicherheit, Transparenz, Optionen.","Zuerst stelle ich sicher, dass das Problem verstanden ist und die Sicherheit nicht betroffen ist. Dann informiere ich sofort die Beteiligten und lege Optionen vor, zum Beispiel einen reduzierten Umfang zum Termin oder den vollen Umfang zwei Wochen später.","sicherheit|risiko|verstanden|analys; informiere|beteiligte|transparent|kommunizier|kunde|leitung; option|umfang|plan|alternative|später"],
  ["Wie erklären Sie komplexe technische Themen Führungskräften ohne Technikhintergrund?||Wie kommunizieren Sie mit Entscheidern außerhalb der Technik?","Erkläre deine Kommunikationsmethode.","Ich beginne mit der Entscheidung, die sie treffen müssen, und den Folgen für Kosten, Zeit und Risiko. Dann nutze ich ein einfaches Bild oder einen Vergleich und lasse die technischen Details für den Anhang.","entscheidung|folgen|auswirkung|kosten|risiko; einfach|bild|beispiel|vergleich|klar; details|anhang|fragen|kurz"]],
 fr:[
  ["Parlez-moi d'une décision technique importante et des compromis qu'elle impliquait.||Décrivez une décision de conception où vous avez dû arbitrer entre des objectifs contradictoires.","Citez les options, vos critères et pourquoi vous avez choisi.","Nous devions choisir entre développer un nouveau contrôleur et adapter un contrôleur existant. J'ai comparé le coût, le risque et le délai de mise sur le marché. Nous avons adapté la plateforme existante, gagné six mois et prévu la nouvelle conception pour la génération suivante.","décision|décidé|choisi|choix|option; coût|risque|délai|critère|arbitr; parce que|gagné|résultat|donc|ainsi"],
  ["Comment accompagnez-vous et faites-vous progresser les ingénieurs juniors ?||Quelle est votre approche du mentorat des collègues moins expérimentés ?","Donnez des exemples concrets de mentorat.","Je confie aux juniors une vraie responsabilité sur une partie bien définie du projet et je les vois chaque semaine. Je relis leur travail avec des questions plutôt qu'avec des réponses, pour qu'ils apprennent à trouver eux-mêmes les solutions.","junior|collègue|équipe|mentor; responsabilit|tâche|semaine|régulièr; retour|questions|relis|apprendre|coach"],
  ["L'échéance ne peut pas bouger, mais les essais montrent un problème. Que faites-vous ?||Votre projet est en retard et un essai clé a échoué. Comment réagissez-vous ?","Montrez vos priorités : sécurité, transparence, options.","D'abord, je m'assure que le problème est compris et que la sécurité n'est pas en jeu. Ensuite, j'informe immédiatement les parties prenantes et je propose des options, par exemple un périmètre réduit dans les délais ou le périmètre complet deux semaines plus tard.","sécurité|risque|compris|analys; informe|parties prenantes|transparen|communiqu|client|direction; option|périmètre|plan|alternative|plus tard"],
  ["Comment expliquez-vous des sujets techniques complexes à des managers non techniques ?||Comment communiquez-vous avec les décideurs hors ingénierie ?","Expliquez votre méthode de communication.","Je commence par la décision qu'ils doivent prendre et l'impact sur le coût, le délai et le risque. Puis j'utilise une image simple ou une comparaison et je garde les détails techniques pour l'annexe.","décision|impact|coût|risque|enjeu; simple|image|exemple|comparaison|clair; détails|annexe|questions|court"]]}},
{id:"iv_lawyer", ctx:"pro", role:"lawyer", kind:"iv", title:{en:"Interview: lawyer",de:"Vorstellungsgespräch: Jurist/in",fr:"Entretien : juriste / avocat(e)"}, turns:{
 en:[
  ["Why did you choose this area of law, and why our firm?||What draws you to commercial law and to our team in particular?","Give a personal reason for the field and a concrete reason for the firm.","I chose commercial law because I enjoy finding practical solutions for businesses. Your firm advises many technology companies, and I would like to combine my legal work with my interest in technology.","law|legal|commercial|contract|corporate|field; because|enjoy|interest|passion; firm|team|clients|companies|advise"],
  ["Tell us about a complex matter you worked on – without confidential details.||Describe a challenging case or transaction you were involved in.","Describe your role, the challenge and the outcome, keeping it anonymous.","I supported a supply contract dispute between two manufacturers. My task was to analyse the contract clauses and prepare the arguments. We reached a settlement that kept the business relationship intact.","case|matter|dispute|contract|transaction; analys|research|prepar|draft|review; settlement|outcome|result|agreed|resolved"],
  ["A client wants a solution you consider legally risky. How do you respond?||What do you do if a client insists on something you think is not compliant?","Show integrity and a client-friendly way to say no.","I explain the risk clearly and in plain language, including possible consequences. Then I offer an alternative that reaches the client's business goal in a compliant way, and I document my advice.","risk|consequence|explain|clearly; alternative|option|solution|instead; complian|legal|ethic|document|advice"],
  ["How do you handle several urgent deadlines at the same time?||How do you organise your work when everything is urgent?","Describe how you prioritise and communicate.","I list all deadlines, check which ones are legally binding and plan backwards from them. If there is a conflict, I talk to the partner early and agree on priorities instead of risking quality.","deadline|urgent|priorit|time; list|plan|calendar|binding|court; talk|inform|agree|partner|communicat"]],
 de:[
  ["Warum haben Sie dieses Rechtsgebiet gewählt, und warum unsere Kanzlei?||Was reizt Sie am Wirtschaftsrecht und speziell an unserem Team?","Nenne einen persönlichen Grund für das Rechtsgebiet und einen konkreten Grund für die Kanzlei.","Ich habe das Wirtschaftsrecht gewählt, weil ich gern praktische Lösungen für Unternehmen finde. Ihre Kanzlei berät viele Technologieunternehmen, und ich möchte meine juristische Arbeit mit meinem Interesse an Technik verbinden.","recht|rechtsgebiet|wirtschaftsrecht|vertrag|juristisch; weil|gern|interess|begeister; kanzlei|team|mandant|unternehmen|berät"],
  ["Erzählen Sie von einem komplexen Mandat – ohne vertrauliche Details.||Beschreiben Sie einen anspruchsvollen Fall oder eine Transaktion, an der Sie beteiligt waren.","Beschreibe deine Rolle, die Herausforderung und das Ergebnis – anonym.","Ich habe einen Rechtsstreit um einen Liefervertrag zwischen zwei Herstellern begleitet. Meine Aufgabe war, die Vertragsklauseln zu prüfen und die Argumentation vorzubereiten. Wir haben einen Vergleich erreicht, der die Geschäftsbeziehung erhalten hat.","fall|mandat|streit|vertrag|transaktion; geprüft|prüfen|analys|recherch|vorbereit|entwurf; vergleich|ergebnis|einigung|gelöst|erreicht"],
  ["Ein Mandant will eine Lösung, die Sie für rechtlich riskant halten. Wie reagieren Sie?||Was tun Sie, wenn ein Mandant auf etwas besteht, das Sie für nicht regelkonform halten?","Zeig Integrität und eine mandantenfreundliche Art, Nein zu sagen.","Ich erkläre das Risiko klar und verständlich, einschließlich möglicher Folgen. Dann biete ich eine Alternative an, die das wirtschaftliche Ziel des Mandanten regelkonform erreicht, und dokumentiere meine Beratung.","risiko|folgen|erkläre|klar|verständlich; alternative|option|lösung|stattdessen; regelkonform|rechtlich|compliance|dokumentier|beratung"],
  ["Wie gehen Sie mit mehreren dringenden Fristen gleichzeitig um?||Wie organisieren Sie Ihre Arbeit, wenn alles eilig ist?","Beschreibe, wie du priorisierst und kommunizierst.","Ich liste alle Fristen auf, prüfe, welche rechtlich verbindlich sind, und plane von dort rückwärts. Gibt es einen Konflikt, spreche ich früh mit dem Partner und stimme Prioritäten ab, statt die Qualität zu gefährden.","frist|dringend|eilig|priorit|zeit; liste|plane|kalender|verbindlich|gericht; spreche|informiere|abstimm|partner|kommunizier"]],
 fr:[
  ["Pourquoi avez-vous choisi ce domaine du droit, et pourquoi notre cabinet ?||Qu'est-ce qui vous attire dans le droit des affaires et dans notre équipe en particulier ?","Donnez une raison personnelle pour le domaine et une raison concrète pour le cabinet.","J'ai choisi le droit des affaires parce que j'aime trouver des solutions pratiques pour les entreprises. Votre cabinet conseille de nombreuses entreprises technologiques, et j'aimerais associer mon travail juridique à mon intérêt pour la technologie.","droit|juridique|affaires|contrat|domaine; parce que|aime|intérêt|passion; cabinet|équipe|clients|entreprises|conseille"],
  ["Parlez-nous d'un dossier complexe sur lequel vous avez travaillé – sans détails confidentiels.||Décrivez une affaire ou une transaction exigeante à laquelle vous avez participé.","Décrivez votre rôle, la difficulté et le résultat, de façon anonyme.","J'ai accompagné un litige sur un contrat de fourniture entre deux fabricants. Ma mission était d'analyser les clauses et de préparer l'argumentation. Nous avons obtenu une transaction qui a préservé la relation commerciale.","dossier|affaire|litige|contrat|transaction; analys|recherch|prépar|rédig|examin; transaction|résultat|accord|résolu|obtenu"],
  ["Un client veut une solution que vous jugez juridiquement risquée. Comment réagissez-vous ?||Que faites-vous si un client insiste sur quelque chose que vous estimez non conforme ?","Montrez votre intégrité et une façon de dire non qui reste orientée client.","J'explique le risque clairement et simplement, y compris les conséquences possibles. Puis je propose une alternative qui atteint l'objectif économique du client de manière conforme, et je documente mon conseil.","risque|conséquence|explique|clairement; alternative|option|solution|plutôt; conforme|juridique|éthique|document|conseil"],
  ["Comment gérez-vous plusieurs délais urgents en même temps ?||Comment organisez-vous votre travail quand tout est urgent ?","Décrivez comment vous priorisez et communiquez.","Je liste tous les délais, je vérifie lesquels sont juridiquement contraignants et je planifie à rebours. En cas de conflit, j'en parle tôt avec l'associé et nous fixons les priorités plutôt que de risquer la qualité.","délai|urgent|priorit|temps; liste|planifie|calendrier|contraignant|tribunal; parle|informe|associé|communiqu|fixons"]]}},
{id:"iv_exec", ctx:"pro", role:"exec", kind:"iv", title:{en:"Interview: executive role",de:"Vorstellungsgespräch: Führungsposition",fr:"Entretien : poste de direction"}, turns:{
 en:[
  ["What would you do in your first hundred days in this role?||If you joined us, how would you approach your first three months?","Structure: listen – decide priorities – first results.","In the first month I would listen: meet the team, key customers and the board. Then I would agree on three priorities with the leadership team, and by day one hundred I would deliver first visible results, for example a clear plan for the delayed product line.","first|month|listen|meet|understand; priorit|plan|strategy|agree; results|deliver|visible|quick win|day"],
  ["Tell us how you led a major change in an organisation.||Describe a transformation you were responsible for. What made it work?","Name the change, how you brought people along and the result.","I led the move to a digital order process across four sites. I explained the reasons openly, involved the site managers in the design and measured progress every month. After one year, order errors dropped by forty percent.","change|transformation|move|introduc; explain|involv|communicat|people|team|together; result|measured|dropped|improved|percent|year"],
  ["What was the hardest decision you had to make as a leader?||Tell us about a difficult decision that affected people in your organisation.","Show responsibility, fairness and what you learned.","The hardest decision was closing a loss-making unit. I made sure we had looked at all alternatives, communicated personally and early, and supported every employee with new positions or fair packages. I learned that transparency builds trust even in hard times.","decision|decid|difficult|hard|closing|restructur; alternative|fair|support|personally|communicat; learned|trust|responsib|transparen"],
  ["How do you measure success in your area?||Which key figures would you use to steer the business?","Combine financial and non-financial measures.","I look at a few balanced key figures: revenue growth and margin, customer satisfaction, on-time delivery and employee engagement. We review them monthly and agree on actions when a figure goes off track.","revenue|margin|profit|growth|cost|financial; customer|satisfaction|delivery|quality|employee|engagement; review|monthly|track|actions|kpi"]],
 de:[
  ["Was würden Sie in Ihren ersten hundert Tagen in dieser Rolle tun?||Wenn Sie bei uns anfangen: Wie gehen Sie die ersten drei Monate an?","Struktur: zuhören – Prioritäten festlegen – erste Ergebnisse.","Im ersten Monat würde ich zuhören: das Team, wichtige Kunden und den Aufsichtsrat kennenlernen. Dann würde ich mit dem Führungsteam drei Prioritäten vereinbaren, und bis zum hundertsten Tag erste sichtbare Ergebnisse liefern, zum Beispiel einen klaren Plan für die verzögerte Produktlinie.","ersten|monat|zuhören|kennenlernen|verstehen; priorit|plan|strategie|vereinbar; ergebnis|liefern|sichtbar|erfolg|tag"],
  ["Erzählen Sie, wie Sie eine große Veränderung in einer Organisation geführt haben.||Beschreiben Sie eine Transformation, für die Sie verantwortlich waren. Was hat sie erfolgreich gemacht?","Nenne die Veränderung, wie du die Menschen mitgenommen hast und das Ergebnis.","Ich habe die Umstellung auf einen digitalen Bestellprozess an vier Standorten geführt. Ich habe die Gründe offen erklärt, die Standortleiter in die Gestaltung einbezogen und den Fortschritt jeden Monat gemessen. Nach einem Jahr sanken die Bestellfehler um vierzig Prozent.","veränderung|umstellung|transformation|einführ; erklärt|einbezogen|kommunizier|mitgenommen|team|gemeinsam; ergebnis|gemessen|sanken|verbessert|prozent|jahr"],
  ["Was war die schwierigste Entscheidung, die Sie als Führungskraft treffen mussten?||Erzählen Sie von einer schwierigen Entscheidung, die Menschen in Ihrer Organisation betroffen hat.","Zeig Verantwortung, Fairness und was du gelernt hast.","Die schwierigste Entscheidung war die Schließung einer verlustreichen Einheit. Ich habe sichergestellt, dass wir alle Alternativen geprüft hatten, habe persönlich und früh kommuniziert und jeden Mitarbeitenden mit neuen Stellen oder fairen Lösungen unterstützt. Ich habe gelernt, dass Transparenz auch in harten Zeiten Vertrauen schafft.","entscheidung|entschied|schwierig|schließung|umstrukturier; alternative|fair|unterstützt|persönlich|kommunizier; gelernt|vertrauen|verantwortung|transparenz"],
  ["Wie messen Sie Erfolg in Ihrem Bereich?||Mit welchen Kennzahlen würden Sie das Geschäft steuern?","Kombiniere finanzielle und nicht-finanzielle Kennzahlen.","Ich achte auf wenige ausgewogene Kennzahlen: Umsatzwachstum und Marge, Kundenzufriedenheit, Liefertreue und Mitarbeiterengagement. Wir besprechen sie monatlich und vereinbaren Maßnahmen, wenn eine Zahl vom Kurs abweicht.","umsatz|marge|gewinn|wachstum|kosten|finanz; kunde|zufriedenheit|liefer|qualität|mitarbeit|engagement; monatlich|besprechen|maßnahmen|kennzahl|kpi"]],
 fr:[
  ["Que feriez-vous pendant vos cent premiers jours dans ce poste ?||Si vous nous rejoigniez, comment aborderiez-vous vos trois premiers mois ?","Structure : écouter – fixer les priorités – premiers résultats.","Le premier mois, j'écouterais : rencontrer l'équipe, les clients clés et le conseil d'administration. Ensuite, je fixerais trois priorités avec l'équipe de direction, et d'ici le centième jour, je livrerais des premiers résultats visibles, par exemple un plan clair pour la gamme de produits en retard.","premier|mois|écouter|rencontrer|comprendre; priorit|plan|stratégie|fixer; résultat|livrer|visible|jour"],
  ["Racontez-nous comment vous avez conduit un changement important dans une organisation.||Décrivez une transformation dont vous étiez responsable. Qu'est-ce qui l'a fait réussir ?","Citez le changement, comment vous avez embarqué les équipes et le résultat.","J'ai piloté le passage à un processus de commande numérique sur quatre sites. J'ai expliqué ouvertement les raisons, associé les directeurs de site à la conception et mesuré les progrès chaque mois. Au bout d'un an, les erreurs de commande ont baissé de quarante pour cent.","changement|transformation|passage|introdu; expliqué|associé|communiqu|équipe|ensemble|embarqu; résultat|mesuré|baissé|amélioré|pour cent|an"],
  ["Quelle a été la décision la plus difficile que vous ayez dû prendre en tant que dirigeant ?||Parlez-nous d'une décision difficile qui a touché des personnes dans votre organisation.","Montrez responsabilité, équité et ce que vous avez appris.","La décision la plus difficile a été la fermeture d'une unité déficitaire. Je me suis assuré que nous avions étudié toutes les alternatives, j'ai communiqué personnellement et tôt, et j'ai accompagné chaque salarié avec un nouveau poste ou une solution équitable. J'ai appris que la transparence crée la confiance, même dans les moments durs.","décision|difficile|fermeture|restructur; alternative|équitable|accompagné|personnellement|communiqu; appris|confiance|responsab|transparence"],
  ["Comment mesurez-vous la réussite dans votre domaine ?||Quels indicateurs utiliseriez-vous pour piloter l'activité ?","Combinez indicateurs financiers et non financiers.","Je suis quelques indicateurs équilibrés : croissance du chiffre d'affaires et marge, satisfaction client, respect des délais de livraison et engagement des collaborateurs. Nous les revoyons chaque mois et décidons d'actions quand un indicateur dérive.","chiffre d'affaires|marge|bénéfice|croissance|coût|financ; client|satisfaction|livraison|qualité|collaborateur|engagement; mois|revoyons|actions|indicateur|kpi"]]}},

/* ---------- SMALL TALK (casual) ---------- */
{id:"st_intern", ctx:"cas", role:"intern", kind:"st", title:{en:"Small talk: first day in the team kitchen",de:"Smalltalk: erster Tag in der Teeküche",fr:"Small talk : premier jour à la machine à café"}, turns:{
 en:[
  ["Hi, you must be the new intern! Welcome. How is your first day going?||Oh hello, I haven't seen you before – are you new here?","Greet back, introduce yourself and say how the day is going.","Hi, yes, I'm Sam, the new intern in the design team. Thanks! It's going well so far – a lot of new names, but everyone is very friendly.","hi|hello|yes; i m|i am|my name; intern|new|team; going well|good|great|friendly|nice"],
  ["Where are you studying?||So what do you study?","Answer and ask a question back.","I study mechanical engineering in Stuttgart. And you – how long have you been working here?","study|studying|university; and you|how long|what about you|how about"],
  ["Six years now. Do you already know where the canteen is? The Tuesday pasta is famous.||By the way, have you found the canteen yet? Lunch is quite good here.","React with interest and keep the conversation going.","Not yet, so that's a great tip, thank you! Do people usually go for lunch together in the team?","great|good|thank|nice|really; together|usually|team|lunch|do people|is it"],
  ["Most of us go around twelve. You're welcome to join us.||We usually go at noon – join us if you like!","Accept politely and close the chat in a friendly way.","I'd love to, thanks! Then see you at twelve. I'd better get back to my desk now.","love to|happy to|thank|great|sounds good; see you|later|twelve|noon; back|desk|now"]],
 de:[
  ["Hallo, du musst die neue Praktikantin oder der neue Praktikant sein! Willkommen. Wie läuft dein erster Tag?||Ach hallo, dich habe ich hier noch nie gesehen – bist du neu?","Grüß zurück, stell dich vor und sag, wie der Tag läuft.","Hallo, ja, ich bin Sam, neu als Praktikant im Konstruktionsteam. Danke! Bisher läuft es gut – viele neue Namen, aber alle sind sehr freundlich.","hallo|hi|ja; ich bin|ich heiße; prakti|neu|team; gut|super|freundlich|nett"],
  ["Wo studierst du denn?||Und was studierst du?","Antworte und stell eine Gegenfrage.","Ich studiere Maschinenbau in Stuttgart. Und du – wie lange arbeitest du schon hier?","studiere|studium|hochschule|uni; und du|wie lange|und bei dir|und wie"],
  ["Jetzt seit sechs Jahren. Weißt du schon, wo die Kantine ist? Die Nudeln am Dienstag sind legendär.||Übrigens, hast du die Kantine schon gefunden? Das Mittagessen ist hier echt gut.","Reagiere interessiert und halte das Gespräch am Laufen.","Noch nicht, das ist also ein super Tipp, danke! Geht ihr im Team normalerweise zusammen essen?","super|gut|danke|toll|echt; zusammen|normalerweise|team|essen|geht ihr"],
  ["Die meisten gehen gegen zwölf. Komm gern mit.||Wir gehen meistens um zwölf – komm doch mit!","Nimm freundlich an und beende das Gespräch nett.","Sehr gern, danke! Dann bis zwölf. Ich gehe jetzt mal zurück an meinen Platz.","gern|danke|super|klingt gut; bis|später|zwölf; zurück|platz|schreibtisch|jetzt"]],
 fr:[
  ["Bonjour, tu dois être le nouveau stagiaire ! Bienvenue. Comment se passe ta première journée ?||Ah bonjour, je ne t'ai jamais vu ici – tu es nouveau ?","Rendez le salut, présentez-vous et dites comment se passe la journée.","Bonjour, oui, je suis Sam, le nouveau stagiaire de l'équipe conception. Merci ! Pour l'instant ça se passe bien – beaucoup de nouveaux noms, mais tout le monde est très sympa.","bonjour|salut|oui; je suis|je m'appelle; stagiaire|nouveau|équipe; bien|super|sympa|gentil"],
  ["Tu étudies où ?||Et tu étudies quoi ?","Répondez et posez une question en retour.","J'étudie le génie mécanique à Stuttgart. Et toi, tu travailles ici depuis combien de temps ?","étudie|études|université|école; et toi|depuis combien|et vous"],
  ["Six ans maintenant. Tu sais déjà où est la cantine ? Les pâtes du mardi sont célèbres.||Au fait, tu as déjà trouvé la cantine ? On mange plutôt bien ici.","Réagissez avec intérêt et faites continuer la conversation.","Pas encore, donc c'est un super conseil, merci ! Vous allez souvent déjeuner ensemble dans l'équipe ?","super|bien|merci|génial|vraiment; ensemble|souvent|équipe|déjeuner|vous allez"],
  ["La plupart d'entre nous y vont vers midi. Viens avec nous si tu veux.||On y va en général à midi – joins-toi à nous !","Acceptez poliment et terminez la discussion de façon sympathique.","Avec plaisir, merci ! Alors à midi. Je retourne à mon bureau maintenant.","plaisir|volontiers|merci|super|d'accord; à midi|à tout à l'heure|à plus|tout à l'heure; retourne|bureau|maintenant"]]}},
{id:"st_grad", ctx:"cas", role:"grad", kind:"st", title:{en:"Small talk: recruiter at a career fair",de:"Smalltalk: Recruiterin auf der Karrieremesse",fr:"Small talk : recruteuse au salon de l'emploi"}, turns:{
 en:[
  ["Hello! Are you enjoying the fair so far?||Hi there, busy day, isn't it? Have you found some interesting stands?","Answer positively and introduce yourself briefly.","Hello! Yes, very much – it's a great chance to talk to companies directly. I'm Robin, I've just finished my master's in electrical engineering.","yes|very|great|enjoy|interesting; i m|i am|my name; finished|master|degree|graduate|studied"],
  ["Nice to meet you. What brings you to our stand?||Great. What made you stop at our stand?","Show that you know something about the company.","I read about your new battery factory and found it very impressive. I'd like to know which graduate positions you offer in that area.","read|heard|saw|know; factory|project|product|company|battery|new; position|job|graduate|offer|opportunit"],
  ["We actually have a trainee programme starting in spring. Have you been to this fair before?||Spring is when our trainees start. Is this your first career fair?","React and keep the small talk going with a light question.","That sounds perfect, thank you. No, it's my first time here. Do you come every year?","sounds|perfect|great|thank; first time|first|never|before; do you|every year|how often|you"],
  ["Every year – it's always good fun. Here is my card, feel free to email me.||Yes, every year. Let me give you my card – just send me your CV.","Thank them, promise a next step and say goodbye.","Thank you very much! I'll send you my CV this week. Enjoy the rest of the fair!","thank; send|email|cv|contact|write; this week|tomorrow|soon; enjoy|have a nice|goodbye|bye"]],
 de:[
  ["Hallo! Gefällt Ihnen die Messe bisher?||Hallo, ganz schön viel los heute, oder? Haben Sie schon interessante Stände gefunden?","Antworte positiv und stell dich kurz vor.","Hallo! Ja, sehr – es ist eine tolle Gelegenheit, direkt mit Unternehmen zu sprechen. Ich bin Robin und habe gerade meinen Master in Elektrotechnik abgeschlossen.","ja|sehr|toll|gefällt|interessant; ich bin|ich heiße|mein name; abgeschlossen|master|abschluss|studium"],
  ["Schön, Sie kennenzulernen. Was führt Sie zu unserem Stand?||Prima. Warum sind Sie bei uns stehen geblieben?","Zeig, dass du etwas über das Unternehmen weißt.","Ich habe von Ihrem neuen Batteriewerk gelesen und fand das sehr beeindruckend. Ich würde gern wissen, welche Einstiegsstellen Sie in dem Bereich anbieten.","gelesen|gehört|gesehen|weiß; werk|projekt|produkt|unternehmen|batterie|neu; stelle|einstieg|job|anbieten|möglichkeit"],
  ["Wir haben tatsächlich ein Traineeprogramm, das im Frühjahr startet. Waren Sie schon einmal auf dieser Messe?||Im Frühjahr starten unsere Trainees. Ist das Ihre erste Karrieremesse?","Reagiere und halte den Smalltalk mit einer leichten Frage am Laufen.","Das klingt perfekt, danke. Nein, ich bin zum ersten Mal hier. Kommen Sie jedes Jahr?","klingt|perfekt|super|danke; ersten mal|erste|noch nie; kommen sie|jedes jahr|wie oft|sie"],
  ["Jedes Jahr – das macht immer Spaß. Hier ist meine Karte, schreiben Sie mir gern eine E-Mail.||Ja, jedes Jahr. Ich gebe Ihnen meine Karte – schicken Sie mir einfach Ihren Lebenslauf.","Bedank dich, kündige einen nächsten Schritt an und verabschiede dich.","Vielen Dank! Ich schicke Ihnen meinen Lebenslauf noch diese Woche. Viel Spaß noch auf der Messe!","dank; schicke|sende|mail|lebenslauf|melde; diese woche|morgen|bald; viel spaß|schönen|tschüss|wiedersehen"]],
 fr:[
  ["Bonjour ! Le salon vous plaît pour l'instant ?||Bonjour, il y a du monde aujourd'hui, non ? Vous avez trouvé des stands intéressants ?","Répondez positivement et présentez-vous brièvement.","Bonjour ! Oui, beaucoup – c'est une excellente occasion de parler directement aux entreprises. Je m'appelle Robin, je viens de terminer mon master en génie électrique.","oui|beaucoup|excellent|plaît|intéressant; je m'appelle|je suis; terminé|master|diplôme|études"],
  ["Enchantée. Qu'est-ce qui vous amène à notre stand ?||Très bien. Pourquoi vous êtes-vous arrêté chez nous ?","Montrez que vous connaissez un peu l'entreprise.","J'ai lu un article sur votre nouvelle usine de batteries et je l'ai trouvé très impressionnant. J'aimerais savoir quels postes pour jeunes diplômés vous proposez dans ce domaine.","lu|entendu|vu|sais; usine|projet|produit|entreprise|batterie|nouvelle; poste|emploi|diplômé|proposez|opportunité"],
  ["Nous avons justement un programme de stagiaires qui commence au printemps. Vous étiez déjà venu à ce salon ?||Nos jeunes diplômés commencent au printemps. C'est votre premier salon de l'emploi ?","Réagissez et poursuivez le small talk avec une question légère.","Ça a l'air parfait, merci. Non, c'est la première fois que je viens. Vous venez chaque année ?","parfait|super|merci|l'air; première fois|premier|jamais; vous venez|chaque année|souvent|vous"],
  ["Chaque année – c'est toujours sympa. Voici ma carte, n'hésitez pas à m'écrire.||Oui, chaque année. Je vous donne ma carte – envoyez-moi simplement votre CV.","Remerciez, annoncez une prochaine étape et dites au revoir.","Merci beaucoup ! Je vous envoie mon CV cette semaine. Bonne fin de salon !","merci; envoie|écris|cv|mail|contact; cette semaine|demain|bientôt; bonne|au revoir|bonne journée"]]}},
{id:"st_eng", ctx:"cas", role:"eng", kind:"st", title:{en:"Small talk: customer before a project meeting",de:"Smalltalk: Kunde vor der Projektbesprechung",fr:"Small talk : client avant une réunion de projet"}, turns:{
 en:[
  ["Good morning! Sorry, I'm a bit early.||Morning! Am I the first one here?","Welcome the customer warmly and offer something.","Good morning, no problem at all – welcome! Can I get you a coffee or some water while we wait for the others?","good morning|morning|welcome|hello; no problem|not at all|great; coffee|water|tea|drink|get you"],
  ["A coffee would be great, thanks. The traffic was terrible this morning.||Coffee, please. The drive here took ages today.","Show sympathy and ask a simple follow-up question.","Oh no, I'm sorry to hear that. Did you come from the airport or from your office in the city?","sorry|oh no|terrible|annoying|hear; did you|where|how|from|come"],
  ["From the office – there's a construction site on the motorway. How are things with you? Busy?||From our office. Anyway, how are you – lots going on?","Answer honestly but positively and give a small detail.","Busy, but in a good way. We have just finished testing the first prototype, so the whole team is quite excited about today's meeting.","busy|lot|good|well|fine; finished|testing|prototype|project|team; excited|looking forward|happy|good"],
  ["Great to hear. Oh, it looks like the others are coming.||Excellent. Ah, here come your colleagues.","Make a smooth transition to the meeting.","Perfect timing. Shall we go to the meeting room? I'll bring your coffee along.","perfect|great|good|right; shall we|let's|go|start|meeting|room; bring|coffee|follow"]],
 de:[
  ["Guten Morgen! Entschuldigung, ich bin etwas zu früh.||Morgen! Bin ich der Erste?","Begrüße den Kunden herzlich und biete etwas an.","Guten Morgen, überhaupt kein Problem – herzlich willkommen! Darf ich Ihnen einen Kaffee oder ein Wasser bringen, während wir auf die anderen warten?","guten morgen|morgen|willkommen|hallo; kein problem|gar nicht|schön; kaffee|wasser|tee|trinken|bringen"],
  ["Ein Kaffee wäre toll, danke. Der Verkehr war heute Morgen furchtbar.||Kaffee, bitte. Die Fahrt hierher hat heute ewig gedauert.","Zeig Mitgefühl und stell eine einfache Nachfrage.","Oh nein, das tut mir leid. Kommen Sie vom Flughafen oder aus Ihrem Büro in der Stadt?","leid|oh nein|furchtbar|ärgerlich|schade; kommen sie|woher|wie|von|aus"],
  ["Aus dem Büro – auf der Autobahn ist eine Baustelle. Und wie läuft es bei Ihnen? Viel zu tun?||Aus unserem Büro. Aber sagen Sie, wie geht es Ihnen – viel los?","Antworte ehrlich, aber positiv, und nenne ein kleines Detail.","Viel zu tun, aber im positiven Sinn. Wir haben gerade die Tests am ersten Prototyp abgeschlossen, deshalb freut sich das ganze Team auf die Besprechung heute.","viel|gut|positiv|prima; abgeschlossen|test|prototyp|projekt|team; freu|gespannt|froh|gut"],
  ["Schön zu hören. Oh, da kommen wohl die anderen.||Prima. Ah, da kommen Ihre Kollegen.","Leite elegant zur Besprechung über.","Perfektes Timing. Wollen wir in den Besprechungsraum gehen? Ich nehme Ihren Kaffee mit.","perfekt|gut|prima|genau; wollen wir|lassen sie uns|gehen|beginnen|besprechung|raum; nehme|kaffee|mit"]],
 fr:[
  ["Bonjour ! Désolé, je suis un peu en avance.||Bonjour ! Je suis le premier ?","Accueillez chaleureusement le client et proposez quelque chose.","Bonjour, aucun problème – bienvenue ! Je vous apporte un café ou de l'eau pendant que nous attendons les autres ?","bonjour|bienvenue; aucun problème|pas de problème|pas du tout; café|eau|thé|boire|apporte"],
  ["Un café, ce serait parfait, merci. La circulation était horrible ce matin.||Un café, s'il vous plaît. Le trajet a pris une éternité aujourd'hui.","Montrez de la compréhension et posez une question simple.","Oh non, je suis désolé. Vous venez de l'aéroport ou de votre bureau en ville ?","désolé|oh non|horrible|pénible|dommage; vous venez|d'où|comment|de|depuis"],
  ["Du bureau – il y a des travaux sur l'autoroute. Et chez vous, ça va ? Beaucoup de travail ?||De notre bureau. Mais dites-moi, comment allez-vous – beaucoup de choses en ce moment ?","Répondez honnêtement mais positivement, avec un petit détail.","Beaucoup de travail, mais dans le bon sens. Nous venons de terminer les essais du premier prototype, donc toute l'équipe a hâte de la réunion d'aujourd'hui.","beaucoup|bien|bon sens|ça va; terminé|essai|prototype|projet|équipe; hâte|content|impatient|ravi"],
  ["Ravi de l'entendre. Oh, on dirait que les autres arrivent.||Très bien. Ah, voici vos collègues.","Faites une transition naturelle vers la réunion.","Parfait, c'est le bon moment. On va dans la salle de réunion ? J'apporte votre café.","parfait|bien|bon moment; on va|allons|salle|réunion|commencer; apporte|café"]]}},
{id:"st_senior", ctx:"cas", role:"senior", kind:"st", title:{en:"Small talk: coffee break at a conference",de:"Smalltalk: Kaffeepause auf der Konferenz",fr:"Small talk : pause café en conférence"}, turns:{
 en:[
  ["That was an interesting talk, wasn't it?||What did you think of the keynote?","Agree and give a short opinion.","Yes, really interesting. I especially liked the part about predictive maintenance – that's exactly what we are working on right now.","yes|really|interesting|liked|agree; especially|part|point|idea; working on|we|our|right now|exactly"],
  ["Oh, which company are you with?||Really? Where do you work, if I may ask?","Say where you work and what you do – briefly.","I'm a senior engineer at a manufacturer of industrial pumps. I lead a small team that develops monitoring systems. And you?","senior|engineer|lead|team|work; company|manufacturer|pumps|systems|develop; and you|what about you"],
  ["I'm in charge of maintenance at a chemical plant. We are just starting to use sensors.||I run maintenance at a chemical site – we're at the beginning with all this.","Show interest and find common ground.","That's great, then we face similar questions from different sides. What has been the biggest challenge so far?","great|interesting|nice|similar|same; challenge|difficult|problem|biggest|so far; what|how|which"],
  ["Mostly getting reliable data. It would be good to exchange ideas sometime.||Honestly, data quality. Maybe we could continue this conversation another time?","Suggest a concrete next step and exchange contacts.","Absolutely, I'd like that. Shall we connect online? Here's my card – I could also send you the article I mentioned.","absolutely|sure|yes|like that|good idea; connect|card|contact|email|linkedin|number; send|article|share|follow up"]],
 de:[
  ["Das war ein interessanter Vortrag, oder?||Wie fanden Sie die Keynote?","Stimm zu und gib eine kurze Meinung.","Ja, wirklich interessant. Besonders gut fand ich den Teil über vorausschauende Wartung – genau daran arbeiten wir gerade.","ja|wirklich|interessant|gut fand|stimmt; besonders|teil|punkt|idee; arbeiten|wir|unser|gerade|genau"],
  ["Ach, bei welchem Unternehmen sind Sie?||Wirklich? Wo arbeiten Sie denn, wenn ich fragen darf?","Sag, wo du arbeitest und was du machst – kurz.","Ich bin Senior-Ingenieur bei einem Hersteller von Industriepumpen. Ich leite ein kleines Team, das Überwachungssysteme entwickelt. Und Sie?","senior|ingenieur|leite|team|arbeite; unternehmen|hersteller|pumpen|systeme|entwickel; und sie|und bei ihnen"],
  ["Ich bin für die Instandhaltung in einem Chemiewerk zuständig. Wir fangen gerade mit Sensoren an.||Ich leite die Instandhaltung an einem Chemiestandort – wir stehen da noch am Anfang.","Zeig Interesse und finde Gemeinsamkeiten.","Das ist ja spannend, dann haben wir ähnliche Fragen von verschiedenen Seiten. Was war bisher die größte Herausforderung?","spannend|interessant|schön|ähnlich|gleich; herausforderung|schwierig|problem|größte|bisher; was|wie|welche"],
  ["Vor allem verlässliche Daten zu bekommen. Es wäre gut, sich mal auszutauschen.||Ehrlich gesagt die Datenqualität. Vielleicht können wir das Gespräch ein andermal fortsetzen?","Schlag einen konkreten nächsten Schritt vor und tauscht Kontakte aus.","Auf jeden Fall, sehr gern. Wollen wir uns online vernetzen? Hier ist meine Karte – ich kann Ihnen auch den Artikel schicken, den ich erwähnt habe.","auf jeden fall|gern|ja|gute idee; vernetzen|karte|kontakt|mail|linkedin|nummer; schicken|artikel|teilen|melde"]],
 fr:[
  ["C'était une conférence intéressante, non ?||Qu'avez-vous pensé de la keynote ?","Approuvez et donnez un court avis.","Oui, vraiment intéressante. J'ai particulièrement aimé la partie sur la maintenance prédictive – c'est exactement ce sur quoi nous travaillons en ce moment.","oui|vraiment|intéressant|aimé|d'accord; particulièrement|partie|point|idée; travaillons|nous|notre|en ce moment|exactement"],
  ["Ah, vous êtes dans quelle entreprise ?||Vraiment ? Où travaillez-vous, si je peux me permettre ?","Dites où vous travaillez et ce que vous faites – brièvement.","Je suis ingénieur senior chez un fabricant de pompes industrielles. Je dirige une petite équipe qui développe des systèmes de surveillance. Et vous ?","senior|ingénieur|dirige|équipe|travaille; entreprise|fabricant|pompes|systèmes|développe; et vous"],
  ["Je suis responsable de la maintenance dans une usine chimique. Nous commençons tout juste à utiliser des capteurs.||Je dirige la maintenance d'un site chimique – nous n'en sommes qu'au début.","Montrez de l'intérêt et trouvez un point commun.","C'est passionnant, nous avons donc des questions similaires de deux côtés différents. Quel a été le plus grand défi jusqu'ici ?","passionnant|intéressant|similaire|même|commun; défi|difficile|problème|plus grand|jusqu'ici; quel|comment|quelle"],
  ["Surtout obtenir des données fiables. Ce serait bien d'échanger un jour.||Honnêtement, la qualité des données. Peut-être pourrions-nous poursuivre cette conversation une autre fois ?","Proposez une prochaine étape concrète et échangez vos coordonnées.","Absolument, avec plaisir. On se connecte en ligne ? Voici ma carte – je peux aussi vous envoyer l'article dont j'ai parlé.","absolument|avec plaisir|oui|bonne idée|volontiers; connecte|carte|contact|mail|linkedin|numéro; envoyer|article|partager"]]}},
{id:"st_lawyer", ctx:"cas", role:"lawyer", kind:"st", title:{en:"Small talk: reception after a legal conference",de:"Smalltalk: Empfang nach einer Juristentagung",fr:"Small talk : cocktail après un colloque juridique"}, turns:{
 en:[
  ["Hello, I don't think we've met. I'm Claire, I work in-house at an energy company.||Good evening! Claire, legal department of an energy company – and you are?","Introduce yourself and react to her job.","Nice to meet you, Claire. I'm Daniel, a lawyer at a firm specialising in commercial contracts. Energy must be a fascinating field at the moment.","nice to meet|pleased|hello; i m|i am|my name|lawyer|firm|attorney; fascinating|interesting|exciting|busy|energy"],
  ["It certainly is – new regulations every month. Did you enjoy the panel on contract law?||Never a dull day! What did you think of the panel discussion?","Give a light, positive comment and ask her opinion.","Yes, I found the discussion on digital signatures very practical. What did you think about it?","yes|found|enjoyed|liked|interesting; practical|useful|discussion|panel|signatures; what did you think|your opinion|and you|how about you"],
  ["I agreed with most of it. Are you here every year?||Mostly useful. Do you come to this conference regularly?","Answer and add a small personal note.","This is my third time. I like it because it's a good mix of practice and theory – and the food is always excellent.","third|second|first|every year|time; like|good|mix|practice|theory; food|coffee|location|city|excellent"],
  ["I have to say goodbye now, I have an early flight tomorrow.||Unfortunately I have to leave – early start tomorrow.","Say goodbye warmly and leave the door open for contact.","Of course – it was a pleasure talking to you. Here's my card, in case you ever need outside advice on contracts. Have a good flight!","of course|sure|pleasure|nice|great; card|contact|email|touch; good flight|safe trip|goodbye|have a"]],
 de:[
  ["Hallo, ich glaube, wir kennen uns noch nicht. Ich bin Claire, ich arbeite in der Rechtsabteilung eines Energieunternehmens.||Guten Abend! Claire, Rechtsabteilung eines Energieversorgers – und Sie sind?","Stell dich vor und reagiere auf ihren Beruf.","Freut mich, Claire. Ich bin Daniel, Anwalt in einer Kanzlei, die auf Wirtschaftsverträge spezialisiert ist. Die Energiebranche ist im Moment sicher sehr spannend.","freut mich|angenehm|hallo; ich bin|ich heiße|anwalt|kanzlei|jurist; spannend|interessant|aufregend|viel los|energie"],
  ["Das kann man wohl sagen – jeden Monat neue Vorschriften. Hat Ihnen das Podium zum Vertragsrecht gefallen?||Langweilig wird es nie! Wie fanden Sie die Podiumsdiskussion?","Gib einen leichten, positiven Kommentar und frag nach ihrer Meinung.","Ja, die Diskussion über digitale Signaturen fand ich sehr praxisnah. Wie fanden Sie sie?","ja|fand|gefallen|interessant; praxis|nützlich|diskussion|podium|signatur; wie fanden sie|ihre meinung|und sie|und ihnen"],
  ["Ich stimme dem meisten zu. Sind Sie jedes Jahr hier?||Größtenteils nützlich. Kommen Sie regelmäßig zu dieser Tagung?","Antworte und ergänze eine kleine persönliche Note.","Ich bin zum dritten Mal hier. Mir gefällt die Mischung aus Praxis und Theorie – und das Essen ist immer ausgezeichnet.","dritten|zweiten|ersten|jedes jahr|mal; gefällt|gut|mischung|praxis|theorie; essen|kaffee|ort|stadt|ausgezeichnet"],
  ["Ich muss mich jetzt leider verabschieden, ich habe morgen einen frühen Flug.||Leider muss ich los – morgen geht es früh weiter.","Verabschiede dich herzlich und lass die Tür für einen Kontakt offen.","Natürlich – es war mir ein Vergnügen. Hier ist meine Karte, falls Sie einmal externe Beratung zu Verträgen brauchen. Guten Flug!","natürlich|klar|vergnügen|schön|freut; karte|kontakt|mail|melden; guten flug|gute reise|auf wiedersehen|tschüss"]],
 fr:[
  ["Bonsoir, je crois que nous ne nous connaissons pas. Je suis Claire, juriste dans une entreprise d'énergie.||Bonsoir ! Claire, service juridique d'un groupe énergétique – et vous êtes ?","Présentez-vous et réagissez à son métier.","Enchanté, Claire. Je suis Daniel, avocat dans un cabinet spécialisé en contrats commerciaux. L'énergie doit être un domaine passionnant en ce moment.","enchanté|ravi|bonsoir; je suis|je m'appelle|avocat|cabinet|juriste; passionnant|intéressant|captivant|énergie"],
  ["C'est le moins qu'on puisse dire – de nouvelles réglementations chaque mois. La table ronde sur le droit des contrats vous a plu ?||On ne s'ennuie jamais ! Qu'avez-vous pensé de la table ronde ?","Faites un commentaire léger et positif et demandez son avis.","Oui, j'ai trouvé la discussion sur les signatures électroniques très concrète. Qu'en avez-vous pensé ?","oui|trouvé|plu|intéressant; concret|pratique|utile|discussion|table ronde|signature; qu'en avez-vous pensé|votre avis|et vous"],
  ["J'étais d'accord avec l'essentiel. Vous venez chaque année ?||Plutôt utile. Vous venez régulièrement à ce colloque ?","Répondez et ajoutez une petite note personnelle.","C'est la troisième fois. J'aime ce colloque parce qu'il mélange pratique et théorie – et le buffet est toujours excellent.","troisième|deuxième|première|chaque année|fois; aime|bien|mélange|pratique|théorie; buffet|repas|café|lieu|ville|excellent"],
  ["Je dois malheureusement vous quitter, j'ai un vol tôt demain.||Malheureusement je dois partir – je commence tôt demain.","Dites au revoir chaleureusement et laissez la porte ouverte à un contact.","Bien sûr – ce fut un plaisir. Voici ma carte, au cas où vous auriez besoin d'un conseil externe sur des contrats. Bon vol !","bien sûr|plaisir|ravi|enchanté; carte|contact|mail|coordonnées; bon vol|bon voyage|au revoir|bonne soirée"]]}},
{id:"st_exec", ctx:"cas", role:"exec", kind:"st", title:{en:"Small talk: business dinner with an investor",de:"Smalltalk: Geschäftsessen mit einer Investorin",fr:"Small talk : dîner d'affaires avec une investisseuse"}, turns:{
 en:[
  ["What a lovely restaurant. Thank you for the invitation.||Thank you for organising this evening – I've heard great things about this place.","Respond graciously and make her feel welcome.","It's our pleasure – thank you for making the time. The chef is known for regional dishes, so I hope you'll enjoy it.","pleasure|welcome|glad|happy|thank; time|coming|evening; chef|food|dishes|menu|enjoy|hope"],
  ["I'm sure I will. How long have you been leading the company now?||So, tell me – how long have you been CEO?","Answer briefly and add something personal but professional.","Almost four years now. Time flies – the first year was mostly about restructuring, but now it's great to see the team growing again.","years|year|since|almost; first|restructur|change|beginning; team|growing|great|proud|again"],
  ["That must be rewarding. Do you still find time for anything outside work?||Impressive. And outside the office – how do you switch off?","Share a hobby and ask her a question back.","I try to – I go sailing whenever I can, it really clears my head. What about you? I hear you travel a lot.","sailing|running|hiking|reading|family|music|sport|cycling; whenever|weekend|try|clears|relax; what about you|and you|how about|do you"],
  ["Mostly for work, but I love discovering new places. Shall we look at the menu?||Far too much travel, honestly! Shall we order?","Agree, and mention that you look forward to discussing business later.","Good idea. Let's enjoy the dinner first – and over dessert I'd be happy to give you a short update on our growth plans.","good idea|yes|let's|sure|of course; enjoy|dinner|menu|order|first; later|dessert|update|plans|discuss|talk"]],
 de:[
  ["Was für ein schönes Restaurant. Vielen Dank für die Einladung.||Danke, dass Sie den Abend organisiert haben – ich habe viel Gutes über dieses Lokal gehört.","Antworte gewinnend und gib ihr das Gefühl, willkommen zu sein.","Sehr gern – danke, dass Sie sich die Zeit nehmen. Der Koch ist für regionale Gerichte bekannt, ich hoffe, es schmeckt Ihnen.","gern|willkommen|freue|danke; zeit|kommen|abend; koch|essen|gerichte|karte|schmeckt|hoffe"],
  ["Davon bin ich überzeugt. Wie lange leiten Sie das Unternehmen jetzt schon?||Erzählen Sie mal – wie lange sind Sie schon CEO?","Antworte kurz und füge etwas Persönliches, aber Professionelles hinzu.","Jetzt fast vier Jahre. Die Zeit vergeht schnell – im ersten Jahr ging es vor allem um Umstrukturierung, aber jetzt ist es schön zu sehen, wie das Team wieder wächst.","jahre|jahr|seit|fast; ersten|umstrukturier|veränderung|anfang; team|wächst|schön|stolz|wieder"],
  ["Das ist sicher erfüllend. Finden Sie noch Zeit für etwas außerhalb der Arbeit?||Beeindruckend. Und abseits vom Büro – wie schalten Sie ab?","Erzähl von einem Hobby und stell eine Gegenfrage.","Ich versuche es – ich gehe segeln, wann immer ich kann, das macht wirklich den Kopf frei. Und Sie? Ich habe gehört, Sie reisen viel.","segeln|laufen|wandern|lesen|familie|musik|sport|rad; wann immer|wochenende|versuche|kopf frei|entspann; und sie|und bei ihnen|reisen sie"],
  ["Meistens beruflich, aber ich entdecke gern neue Orte. Wollen wir in die Karte schauen?||Viel zu viel, ehrlich gesagt! Wollen wir bestellen?","Stimm zu und erwähne, dass du dich auf das geschäftliche Gespräch später freust.","Gute Idee. Genießen wir zuerst das Essen – und beim Dessert gebe ich Ihnen gern ein kurzes Update zu unseren Wachstumsplänen.","gute idee|ja|gern|natürlich; genießen|essen|karte|bestellen|zuerst; später|dessert|update|pläne|besprechen"]],
 fr:[
  ["Quel beau restaurant. Merci pour l'invitation.||Merci d'avoir organisé cette soirée – on m'a dit beaucoup de bien de cet endroit.","Répondez avec élégance et mettez-la à l'aise.","C'est avec plaisir – merci de nous accorder votre temps. Le chef est réputé pour ses plats régionaux, j'espère que vous apprécierez.","plaisir|bienvenue|ravi|merci; temps|venue|soirée; chef|plats|cuisine|carte|apprécier|espère"],
  ["J'en suis sûre. Depuis combien de temps dirigez-vous l'entreprise ?||Alors, dites-moi – depuis quand êtes-vous PDG ?","Répondez brièvement et ajoutez une touche personnelle mais professionnelle.","Bientôt quatre ans. Le temps passe vite – la première année était surtout consacrée à la restructuration, mais aujourd'hui c'est formidable de voir l'équipe grandir à nouveau.","ans|année|depuis|bientôt; première|restructur|changement|début; équipe|grandir|formidable|fier|nouveau"],
  ["Ce doit être gratifiant. Trouvez-vous encore du temps pour autre chose que le travail ?||Impressionnant. Et en dehors du bureau – comment décrochez-vous ?","Parlez d'un loisir et posez une question en retour.","J'essaie – je fais de la voile dès que je peux, ça me vide vraiment la tête. Et vous ? On m'a dit que vous voyagiez beaucoup.","voile|course|randonnée|lecture|famille|musique|sport|vélo; dès que|week-end|essaie|vide la tête|détend; et vous|voyagez"],
  ["Surtout pour le travail, mais j'adore découvrir de nouveaux endroits. On regarde la carte ?||Beaucoup trop, honnêtement ! On commande ?","Approuvez et dites que vous serez ravi de parler affaires plus tard.","Bonne idée. Profitons d'abord du dîner – et au dessert, je vous présenterai volontiers un bref point sur nos projets de croissance.","bonne idée|oui|volontiers|bien sûr; profitons|dîner|carte|commander|d'abord; plus tard|dessert|point|projets|parler"]]}}
);
const ROLES=["intern","grad","eng","senior","lawyer","exec"];
Object.assign(T.en,{role_title:"Career level", role_all:"All", role_intern:"Internship", role_grad:"Graduate", role_eng:"Engineer", role_senior:"Senior engineer", role_lawyer:"Lawyer", role_exec:"Executive", kind_iv:"Interview", kind_st:"Small talk", role_desc:"Interviews and small talk for your career stage – the partner varies the questions each time."});
Object.assign(T.de,{role_title:"Karrierestufe", role_all:"Alle", role_intern:"Praktikum", role_grad:"Berufseinstieg", role_eng:"Ingenieur/in", role_senior:"Senior-Ingenieur/in", role_lawyer:"Jurist/in", role_exec:"Führungskraft", kind_iv:"Interview", kind_st:"Smalltalk", role_desc:"Vorstellungsgespräche und Smalltalk für deine Karrierestufe – das Gegenüber variiert die Fragen jedes Mal."});
